func makeRunHandler(f *policy.File, auditLog *audit.Logger, sessionID string, policyPath string) func(context.Context, mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	return func(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
		cmdID := strings.TrimSpace(req.GetString("command_id", ""))
		argv := req.GetStringSlice("argv", nil)
		if (cmdID == "" && len(argv) == 0) || (cmdID != "" && len(argv) != 0) {
			return mcplib.NewToolResultError("provide exactly one of command_id (strict policy mode) or argv (trusted workspace mode)"), nil
		}
		if len(argv) > 0 {
			environment, waitErr := awaitWorkspaceAuthorization(ctx, f, policyPath, sessionID, argv)
			if waitErr != nil {
				return mcplib.NewToolResultError(waitErr.Error()), nil
			}
			res, runErr := executeWorkspace(ctx, projectRoot(policyPath), environment, argv, execution.Options{
				Stdout: os.Stderr, Stderr: os.Stderr, Audit: auditLog, SessionID: sessionID,
				AllowWorkspaceNetwork: true, // The approved workspace grant promises normal network access.
			})
			if runErr != nil {
				return mcplib.NewToolResultError(fmt.Sprintf("workspace execution error: %v", runErr)), nil
			}
			return runResult(res), nil
		}
		current, authorizedEnvironment, waitErr := awaitRunAuthorization(ctx, f, policyPath, sessionID, cmdID)
		if waitErr != nil {
			return mcplib.NewToolResultError(waitErr.Error()), nil
		}

		res, runErr := executeCommand(ctx, current, policyPath, projectRoot(policyPath), cmdID, execution.Options{
			Environment: authorizedEnvironment,
			Stdout:      os.Stderr, Stderr: os.Stderr, // redacted live stream
			Audit: auditLog, SessionID: sessionID,
		})
		if runErr != nil {
			return mcplib.NewToolResultError(fmt.Sprintf("execution error: %v", runErr)), nil
		}

		return runResult(res), nil
	}
}

func awaitRunAuthorization(ctx context.Context, startup *policy.File, policyPath, sessionID, commandID string) (*policy.File, string, error) {
	root := projectRoot(policyPath)
	requests, err := access.Open(root)
	if err != nil {
		return nil, "", errors.New("local access state is unavailable")
	}
	tracked := map[string]bool{}
	var waitUntil time.Time
	wasProposed := false
	for {
		for id := range tracked {
			request, requestErr := requests.Request(id)
			if requestErr == nil && (request.Status == access.StatusDenied || request.Status == access.StatusExpired) {
				return nil, "", fmt.Errorf("sealed run %s: request %s was %s", commandID, id, request.Status)
			}
		}
		if !waitUntil.IsZero() && !time.Now().Before(waitUntil) {
			return nil, "", fmt.Errorf("sealed run %s: human approval request expired", commandID)
		}

		current, reloadErr := currentPolicy(startup, policyPath)
		if reloadErr != nil {
			return nil, "", fmt.Errorf("policy reload failed: %v", reloadErr)
		}
		pCmd, lookupErr := current.Lookup(commandID)
		if lookupErr != nil {
			proposals, loadErr := pending.Load(pending.Path(policyPath))
			if loadErr != nil {
				return nil, "", errors.New("pending command state is unavailable")
			}
			if proposals.Find(commandID) == nil {
				if wasProposed {
					return nil, "", fmt.Errorf("command %q was rejected or removed before approval", commandID)
				}
				hint := fmt.Sprintf("command %q not found in policy.", commandID)
				if current.AllowProposals {
					hint += " Call propose_command with the exact argv; run_sealed will wait and resume after human approval."
				}
				return nil, "", errors.New(hint)
			}
			wasProposed = true
			if waitUntil.IsZero() {
				waitUntil = time.Now().Add(access.DefaultRequestTTL)
			}
			if err := waitForChange(ctx); err != nil {
				return nil, "", fmt.Errorf("sealed run %s cancelled while waiting for command approval", commandID)
			}
			continue
		}

		environment, envErr := resolveExecutionEnvironment(current, policyPath)
		if envErr != nil {
			return nil, "", errors.New("project environment is unavailable")
		}
		missing, secretRequests, secretErr := requestMissingSecrets(current, pCmd, policyPath, sessionID, environment, requests)
		if secretErr != nil {
			return nil, "", secretErr
		}
		for _, request := range secretRequests {
			tracked[request.ID] = true
			if waitUntil.IsZero() || request.ExpiresAt.Before(waitUntil) {
				waitUntil = request.ExpiresAt
			}
		}

		leaseReady := true
		if current.RequireAgentLeases {
			if authErr := requests.Authorize(sessionID, environment, commandID); authErr != nil {
				leaseReady = false
				request, createErr := requests.CreateLeaseRequest(sessionID, environment, []string{commandID}, access.DefaultLeaseTTL, "run_sealed is waiting for human review")
				if createErr != nil {
					return nil, "", fmt.Errorf("could not create lease request: %v", createErr)
				}
				tracked[request.ID] = true
				if waitUntil.IsZero() || request.ExpiresAt.Before(waitUntil) {
					waitUntil = request.ExpiresAt
				}
			}
		}
		if !missing && leaseReady {
			// Environment remains pinned from the authorization check through
			// execution even if another user action changes the active set.
			pinnedEnvironment := environment
			if !current.UsesEnvironmentEntries() && current.EnvironmentSet != "active" {
				pinnedEnvironment = ""
			}
			return current, pinnedEnvironment, nil
		}
		if err := waitForChange(ctx); err != nil {
			return nil, "", fmt.Errorf("sealed run %s cancelled while waiting for human review", commandID)
		}
	}
}

func awaitWorkspaceAuthorization(ctx context.Context, startup *policy.File, policyPath, sessionID string, argv []string) (string, error) {
	root := projectRoot(policyPath)
	requests, err := access.Open(root)
	if err != nil {
		return "", errors.New("local access state is unavailable")
	}
	current, err := currentPolicy(startup, policyPath)
	if err != nil {
		return "", errors.New("policy reload failed")
	}
	environment, err := resolveExecutionEnvironment(current, policyPath)
	if err != nil {
		return "", errors.New("project environment is unavailable")
	}
	if _, authErr := requests.AuthorizeWorkspace(sessionID, environment); authErr == nil {
		return environment, nil
	}
	request, err := requests.CreateWorkspaceRequest(sessionID, environment, argv, access.DefaultWorkspaceTTL, "agent requested trusted workspace access")
	if err != nil {
		return "", fmt.Errorf("could not create workspace access request: %v", err)
	}
	for {
		if request.Status == access.StatusDenied || request.Status == access.StatusExpired {
			return "", fmt.Errorf("trusted workspace request %s was %s", request.ID, request.Status)
		}
		if _, authErr := requests.AuthorizeWorkspace(sessionID, environment); authErr == nil {
			return environment, nil
		}
		if !time.Now().Before(request.ExpiresAt) {
			return "", errors.New("trusted workspace request expired")
		}
		if err := waitForChange(ctx); err != nil {
			return "", errors.New("workspace run cancelled while waiting for human trust")
		}
		request, _ = requests.Request(request.ID)
	}
}

// AuthorizeWorkspace returns the exact active grant, pinning the environment
// used by the caller through execution. Paused, expired, revoked, and
// cross-session grants all fail closed.
func (m *Manager) AuthorizeWorkspace(sessionID, environment string) (WorkspaceGrant, error) {
	st, err := m.load()
	if err != nil {
		return WorkspaceGrant{}, err
	}
	now := m.now().UTC()
	for _, grant := range st.WorkspaceGrants {
		if grant.SessionID == sessionID && grant.ProjectRoot == m.root && grant.Environment == environment && grant.PausedAt == nil && grant.RevokedAt == nil && now.Before(grant.ExpiresAt) {
			return grant, nil
		}
	}
	return WorkspaceGrant{}, ErrUnauthorized

	var cleanup func() error
	if files != nil {
		cleanup = files.Close
	}
	if opts.EmitGitHubMasks {
		emitGitHubMasks(resolved, redactValues)
	}
	return runner.Run(ctx, pCmd, runner.Options{
		Stdout: opts.Stdout, Stderr: opts.Stderr, WorkDir: root,
		Secrets: resolved, RedactValues: redactValues, AuditSecrets: auditSecrets, Seccomp: &seccompOn, Audit: opts.Audit, SessionID: opts.SessionID,
		Cleanup: cleanup, AllowShell: opts.AllowShell,
		DisableEntropyScan: opts.DisableEntropyScan, AllowPullRequestTarget: opts.AllowPullRequestTarget,
		NoSeal: opts.NoSeal,
	})
}

// environment resolution, temporary file workspace, redaction, CI protection,
// and audit path as strict policy commands. Authorization and environment
// pinning remain the caller's responsibility.
func RunWorkspace(ctx context.Context, root, environment string, argv []string, opts Options) (*runner.Result, error) {
	if len(argv) == 0 || argv[0] == "" {
		return nil, fmt.Errorf("workspace execution requires argv")
	}
	if environment == "" {
		return nil, fmt.Errorf("workspace execution requires a pinned environment")
	}
	manager, err := openEnvironment(root)
	if err != nil {
		return nil, fmt.Errorf("environment store unavailable: %w", err)
	}
	set, ok := manager.Set(environment)
	if !ok || manager.Expired(set) {
		return nil, fmt.Errorf("environment %q is unavailable", environment)
	}
	names := make([]string, 0, len(set.Entries))
	for _, entry := range set.Entries {
		names = append(names, entry.Name)
	}
	// The transient file is never written to disk. Version two directs Run to
	// resolve each entry from the encrypted local environment store.
	f := &policy.File{
		Version:  policy.SupportedVersionV2,
		Provider: "passthrough",
		Commands: []policy.Command{{ID: "workspace", Argv: append([]string(nil), argv...), Secrets: names, AllowNetwork: opts.AllowWorkspaceNetwork}},
	}
	opts.Environment = environment
	opts.AllowShell = true
	res, err := Run(ctx, f, "", root, "workspace", opts)
	if err != nil {
		return nil, err
	}
	return res, nil
}

// HasSecrets reports whether the command carries secrets — either via the v1
// provider refs (Env) or the v2 environment-entry bindings (Secrets).
func (c Command) HasSecrets() bool {
	return len(c.Env) > 0 || len(c.Secrets) > 0
}

// EffectiveNoNetwork resolves whether network isolation must be enforced for
// this command. Posture is default-deny for secret-bearing commands: an
// explicit no_network: true always denies; an explicit allow_network: true
// opts out; otherwise a command that carries secrets gets no network, and a
// command without secrets keeps network access.
func (c Command) EffectiveNoNetwork() bool {
	if c.NoNetwork {
		return true
	}
	if c.AllowNetwork {
		return false
	}
	return c.HasSecrets()
}

// max_bytes is enforced by capWriter, DOWNSTREAM of redaction, so we can
// report Truncated only when bytes were actually dropped (not merely when
// output reached the cap exactly). The redactor's own cap is left unlimited.
// cancelOnErr cancels the run if the live sink can no longer be written.
maxBytes := cmd.MaxBytes
stdoutCap := &capWriter{w: io.MultiWriter(&stdoutBuf, cancelOnErr{outDst, cancel}), max: maxBytes}
stderrCap := &capWriter{w: io.MultiWriter(&stderrBuf, cancelOnErr{errDst, cancel}), max: maxBytes}
stdoutW := redact.New(stdoutCap, secretValues, 0)
stderrW := redact.New(stderrCap, secretValues, 0)

// Build environment: inherit current env, then inject secrets.
childEnv := buildEnv(opts.Env, opts.Secrets)

// Construct the command.
c := exec.CommandContext(runCtx, bin, cmd.Argv[1:]...)
c.Env = childEnv
c.Stdout = stdoutW
c.Stderr = stderrW
c.Dir = workDir

// Apply network isolation. This is a security control, so it FAILS CLOSED:
// if isolation cannot be enforced (unsupported platform, missing sandbox-exec),
// we refuse to run rather than execute with the network wide open.
// Default-deny: secret-bearing commands get no network unless the policy
// explicitly opts out (allow_network: true); see EffectiveNoNetwork.
if cmd.EffectiveNoNetwork() {
	if err := applyNetworkIsolation(c); err != nil {
		return nil, err
	}
}

// applyNetworkIsolation configures the Cmd to run with network access blocked.
// On Linux: a new network namespace (CLONE_NEWNET; needs unprivileged userns).
// On macOS: sandbox-exec with a deny-all network profile.
// On any other platform — or when the platform mechanism is unavailable — it
// returns ErrNoNetworkUnsupported so the caller can FAIL CLOSED.
func applyNetworkIsolation(c *exec.Cmd) error {
	switch runtime.GOOS {
	case "linux":
		return applyLinuxNetworkIsolation(c)
	case "darwin":
		return applyDarwinNetworkIsolation(c)
	default:
		return fmt.Errorf("%w: no implementation for GOOS=%s", ErrNoNetworkUnsupported, runtime.GOOS)
	}
}
